/**
 * LevelCheck theme-specific objective question banks.
 *
 * Where the original shared CEFR bank served all variants identically (differing
 * only by theme tag, ordering and difficulty), this module hands each of the 15
 * LevelCheck themes its own, genuinely distinct set of objective items
 * (grammar / vocabulary / reading / listening) for every CEFR band.
 *
 * 15 themes × 7 levels × ~10 items ≈ 1,050 unique objective questions, so each
 * essay/sitting is theme-coherent and feels like a different assessment.
 *
 * `THEME_OBJECTIVE_BANKS[theme][level]` → Template[] consumed by buildBank().
 */

import type { CEFRLevel, SkillKey } from "./levelquest";

export interface ThemeTemplate {
  skill: SkillKey;
  subskill: string;
  prompt: string;
  options: string[];
  answer: string;
  explanation: string;
  audioText?: string;
}

type LevelBank = Record<CEFRLevel, ThemeTemplate[]>;

/**
 * Compact item helper. Two accepted shapes, told apart by whether the 2nd
 * positional argument (after skill/subskill) is an array:
 *  - prompt-first: T(skill, subskill, prompt, options[], answer, explanation, audioText?)
 *  - listening:    T("listening", subskill, audioText, prompt, options[], answer, explanation)
 */
function T(skill: SkillKey, subskill: string, ...args: (string | string[] | undefined)[]): ThemeTemplate {
  if (Array.isArray(args[1])) {
    const [prompt, options, answer, explanation, audioText] = args as [string, string[], string, string, string | undefined];
    return { skill, subskill, prompt, options, answer, explanation, ...(audioText ? { audioText } : {}) };
  }
  const [audioText, prompt, options, answer, explanation] = args as [string, string, string[], string, string];
  return { skill, subskill, prompt, options, answer, explanation, audioText };
}

